<?php
if(!defined('ABSPATH'))exit;
function legacyx_business_defaults(){return array('entity_type'=>'','state'=>'','formation_status'=>'Not Reviewed','ein_status'=>'Not Reviewed','banking_status'=>'Not Reviewed','compliance_status'=>'Not Reviewed','operations_stage'=>'Foundation','strategic_goal'=>'','next_action'=>'Complete your business foundation and compliance review with your Legacy X Firm advisor.','readiness_steps'=>array('Entity & Ownership','Identity & EIN','Licenses & Compliance','Banking & Financial Organization','Operations & Systems','Strategy & Growth','Capital & Expansion Readiness'));}
function legacyx_business_get_client_data($id){$saved=get_post_meta($id,'_legacyx_business_center',true);return wp_parse_args(is_array($saved)?$saved:array(),legacyx_business_defaults());}
function legacyx_business_admin_box(){add_meta_box('legacyx_business_center','Business Center — Enterprise Profile','legacyx_business_render_admin_box','legacyx_client','normal','default');}add_action('add_meta_boxes','legacyx_business_admin_box');
function legacyx_business_render_admin_box($post){$d=legacyx_business_get_client_data($post->ID);wp_nonce_field('legacyx_save_business_center','legacyx_business_nonce');$fields=array('entity_type'=>'Entity Type','state'=>'Formation State / Jurisdiction','formation_status'=>'Formation Status','ein_status'=>'EIN / Tax ID Status','banking_status'=>'Business Banking Status','compliance_status'=>'Compliance Status','operations_stage'=>'Operations Stage','strategic_goal'=>'Primary Strategic Goal');echo '<div style="display:grid;grid-template-columns:1fr 1fr;gap:14px">';foreach($fields as $k=>$l)echo '<p><label style="display:block;font-weight:600;margin-bottom:6px">'.esc_html($l).'</label><input style="width:100%" name="legacyx_business['.esc_attr($k).']" value="'.esc_attr($d[$k]).'"></p>';echo '</div><p><label style="display:block;font-weight:600;margin-bottom:6px">Next Recommended Action</label><textarea style="width:100%;min-height:80px" name="legacyx_business[next_action]">'.esc_textarea($d['next_action']).'</textarea></p>';}
function legacyx_business_save($id){if(get_post_type($id)!=='legacyx_client'||!isset($_POST['legacyx_business_nonce'])||!wp_verify_nonce(sanitize_text_field(wp_unslash($_POST['legacyx_business_nonce'])),'legacyx_save_business_center')||!current_user_can('edit_post',$id)||!isset($_POST['legacyx_business'])||!is_array($_POST['legacyx_business']))return;$raw=wp_unslash($_POST['legacyx_business']);$d=legacyx_business_get_client_data($id);foreach(array('entity_type','state','formation_status','ein_status','banking_status','compliance_status','operations_stage','strategic_goal') as $k)if(isset($raw[$k]))$d[$k]=sanitize_text_field($raw[$k]);if(isset($raw['next_action']))$d['next_action']=sanitize_textarea_field($raw['next_action']);update_post_meta($id,'_legacyx_business_center',$d);}add_action('save_post_legacyx_client','legacyx_business_save',30);
